+#[test]
+fn haas_keeps_the_fraction_of_an_mm_feed() {
+    // #3692 / #3694: 12.4 mm/min posts as F12.4, never F12.
+    let s = MILL.replace("F 600000", "F 12400");
+    let out = post(&s, "mm").unwrap_or_else(|e| panic!("{e}"));
